mapper.select:
SELECT FROM APPROVAL_DOC D LEFT JOIN APP_USER DU ON DU.USER_ID = D.DRAFTER_ID LEFT JOIN APP_USER AU ON AU.USER_ID = D.APPROVER_ID
AND D.DRAFTER_ID = #{drafterId}
AND D.APPROVER_ID = #{approverId} AND D.STATUS = 'SUBMITTED'
AND D.STATUS = #{status}
AND (D.TITLE LIKE '%' || #{searchKeyword} || '%' OR D.DRAFTER_ID LIKE '%' || #{searchKeyword} || '%' OR DU.USER_NM LIKE '%' || #{searchKeyword} || '%')
ORDER BY D.REGIST_DT DESC, D.DOC_ID DESC LIMIT 200

mapper.insert:
INSERT INTO APPROVAL_DOC (
	DOC_ID, DOC_TYPE, TITLE, CONTENT, DRAFTER_ID, APPROVER_ID, STATUS, REGIST_DT
) VALUES (
	#{docId}, #{docType}, #{title}, #{content}, #{drafterId}, #{approverId}, #{status}, CURRENT_TIMESTAMP
)

mapper.delete:
DELETE FROM APPROVAL_DOC
WHERE DOC_ID = #{docId}
	AND DRAFTER_ID = #{drafterId}
	AND STATUS = 'DRAFT'

mapper.update:
UPDATE APPROVAL_DOC
SET STATUS = 'CANCELLED',
	UPDT_DT = CURRENT_TIMESTAMP
WHERE DOC_ID = #{docId}
	AND DRAFTER_ID = #{drafterId}
	AND STATUS = 'SUBMITTED'
